function convertMarkdownToCells(content) {
  const cells = [];
  const sections = content.split(/(?=^# )/gm).filter((s2) => s2.trim());
  if (sections.length === 0) {
    return [
      {
        type: "notebook_cells",
        attributes: {
          definition: {
            type: "markdown",
            text: content.trim()
          }
        }
      }
    ];
  }
  sections.forEach((section) => {
    const trimmed = section.trim();
    if (trimmed) {
      cells.push({
        type: "notebook_cells",
        attributes: {
          definition: {
            type: "markdown",
            text: trimmed
          }
        }
      });
    }
  });
  return cells;
}
